const fs=require('fs'),path=require('path'),crypto=require('crypto');
const base='/tmp/ticket10-checks/approved-workspace/.scratch/reading-list';
const names=['spec.md','ticket-proposal.md','milestones.md','README.md',...fs.readdirSync(base+'/issues').map(x=>'issues/'+x)];
let count=0;const errors=[];
function anchors(s){return s.split('\n').filter(x=>/^#{1,6} /.test(x)).map(x=>x.replace(/^#+ /,'').toLowerCase().replace(/[^\p{L}\p{N}_\- ]/gu,'').replace(/ /g,'-'));}
for(const name of names){
 const s=fs.readFileSync(path.join(base,name),'utf8');
 for(const m of s.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  if(m[1].startsWith('http'))continue;
  count++; const [file,anchor]=m[1].split('#'); const target=file?path.resolve(path.dirname(path.join(base,name)),file):path.join(base,name);
  if(!fs.existsSync(target)){errors.push(name+' missing '+m[1]);continue;}
  if(anchor&&!anchors(fs.readFileSync(target,'utf8')).includes(anchor))errors.push(name+' missing anchor '+m[1]);
 }
}
for(const name of names.filter(x=>x.startsWith('issues/'))){
 const text=fs.readFileSync(path.join(base,name),'utf8');
 if(!text.includes('**Plan version:** [v1]')||!text.includes('- [ ]')||text.includes('- [x]'))errors.push(name+' version/criteria');
}
if(errors.length) {console.log(errors.join('\n'));process.exit(1);}
const hashes={};for(const n of ['spec.md','ticket-proposal.md'])hashes[n]=crypto.createHash('sha256').update(fs.readFileSync(base+'/drafts/v1/'+n)).digest('hex');
console.log(JSON.stringify({files:names.length,linksChecked:count,errors:0,issues:5,cadence:'2/2/1',draftHashes:hashes},null,2));

