const fs = require('fs');
const path = require('path');
const root = '/tmp/ticket10-checks/approved-workspace';
const base = path.join(root, '.scratch/reading-list');
const draft = path.join(base, 'drafts/v1');
const spec0 = fs.readFileSync(path.join(draft,'spec.md'),'utf8');
const prop0 = fs.readFileSync(path.join(draft,'ticket-proposal.md'),'utf8');
const ids = [...prop0.matchAll(/^## (\d{2}): (.+)$/gm)].map(x=>x[1]);
const edges = {'01':[],'02':['01'],'03':['01'],'04':['01','03'],'05':['01']};
const groups = {'M1':['01','02'],'M2':['03','04'],'M3':['05']};
function assert(x,m){ if(!x) throw new Error(m); }
assert(ids.join(',') === '01,02,03,04,05','unique ordered IDs');
assert(Object.values(groups).flat().sort().join(',') === ids.join(','),'exactly one milestone per ticket');
assert(Object.values(groups).map(x=>x.length).join('/') === '2/2/1','cadence');
const gid = Object.fromEntries(Object.entries(groups).flatMap(([g,x],i)=>x.map(n=>[n,i])));
for(const [id,deps] of Object.entries(edges)) for(const dep of deps) {
 assert(ids.includes(dep) && dep < id,'existing acyclic dependency');
 assert(gid[dep]<=gid[id], 'dependency group order');
}
assert(prop0.includes('cumulatively covers **01, 02, 03, 04, 05**'),'final coverage');
assert(prop0.includes('**High** override, applying to repair too'),'04 override');
assert(spec0.includes('250K') && spec0.includes('python -m unittest discover -s tests'),'roles and gate');
for(const id of ids) {
 const block = prop0.split(new RegExp(`^## ${id}: `,'m'))[1].split(/^## /m)[0];
 assert(block.includes('### Acceptance criteria') && block.includes('### Verification') && block.includes('- [ ]'),'complete unchecked body '+id);
}
for(const f of ['spec.md','ticket-proposal.md','milestones.md','README.md','issues']) assert(!fs.existsSync(path.join(base,f)), 'unrelated/approved destination collision '+f);
const approval = '**Approved plan v1** · Approval: [session input 3](../../../approved-session.md#input-3-verbatim). The human approved the complete displayed v1 bundle, including command spellings, all ticket bodies, milestone definitions, roles and testing. Plan approval only; no QA acceptance, implementation or run launch.';
function baseLinks(s){return s.replaceAll('../../../../GLOSSARY.md','../../GLOSSARY.md').replaceAll('../../../../AGENTS.md','../../AGENTS.md').replaceAll('../../../../../approved-session.md','../../../approved-session.md');}
let spec=baseLinks(spec0).replace('**Draft — unapproved** · Plan version **v1** · No prior version.',approval+' No prior version.');
spec=spec.replace(/Shared understanding confirmed[^\n]*\n/,'Shared understanding was confirmed in session input 2; coherent publication was explicitly approved in session input 3. See the complete [approved proposal](ticket-proposal.md) and [milestones](milestones.md).\n');
spec=spec.replace('This draft has not been approved or published; review must confirm ticket granularity, edges, QA and the coherent bundle.','The approved bundle is published locally. Command spellings, granularity, edges and QA were explicitly confirmed in session input 3. No execution or QA acceptance is claimed.');
let proposal=baseLinks(prop0).replace('**Draft — unapproved** · **v1** · Initial proposal; no earlier published version.',approval+' Initial approved plan; no prior version.');
proposal=proposal.replace(/Review together[^\n]+/,'Published with the complete [spec](spec.md), [milestones](milestones.md), [index](README.md) and individual tickets linked below.');
proposal=proposal.replace('All tickets are proposed `ready-for-agent`','All tickets are `ready-for-agent`').replaceAll('ready-for-agent (proposed).','ready-for-agent.');
proposal=proposal.slice(0,proposal.indexOf('## Review questions and approval scope'))+'## Review resolution and publication approval\n\nShared understanding in session input 2 authorized drafting only. Session input 3 explicitly approved the complete displayed v1 bundle and all command spellings, granularity, edges, testing/role contracts and milestone definitions. No revisions were requested. Publication is local to this isolated workspace. This approval does not accept QA, start implementation or launch a run.\n';
const files={ 'spec.md':spec, 'ticket-proposal.md':proposal };
const slugs=['add-and-list-persistent-entries','mark-entries-read','export-portable-csv','import-csv-while-skipping-duplicates','search-titles-and-authors'];
for(let i=0;i<ids.length;i++){
 const id=ids[i]; const match=proposal.match(new RegExp(`^## ${id}: ([\\s\\S]*?)(?=^## |$)`,'m'));
 // Use heading positions, since multiline $ would otherwise match a single line.
 const start=proposal.indexOf('## '+id+': ');
 const stop=proposal.indexOf('\n## ',start+1);
 let body=proposal.slice(start,stop<0?undefined:stop).replace(/^## /,'# ');
 body=body.replaceAll('(spec.md','(../spec.md').replaceAll('(../../GLOSSARY.md','(../../../GLOSSARY.md').replaceAll('(../../AGENTS.md','(../../../AGENTS.md');
 body=body.replace(/\]\(#(m[123][^)]+)\)/g,'](../milestones.md#$1)').replace(/\]\(#(\d{2}-[^)]+)\)/g,'](../ticket-proposal.md#$1)');
 body=body.replace('**Role guidance:** Inherit shared project defaults; no role additions.','**Role guidance:** Inherit [project defaults](../spec.md#role-configuration); no additions for worker, repair, Spec or Standards.');
 body+='\nAll roles use the [approved role configuration](../spec.md#role-configuration); verification includes the cumulative `python -m unittest discover -s tests` CLI regression gate and its evidence contract.\n';
 files['issues/'+id+'-'+slugs[i]+'.md']=body;
 proposal += `\n- [${id}: ${slugs[i].replaceAll('-',' ')}](issues/${id}-${slugs[i]}.md)`;
}
files['ticket-proposal.md']=proposal+'\n';
const milestoneStart=proposal.indexOf('## Milestone contract');
const milestoneEnd=proposal.indexOf('## Review resolution',milestoneStart);
files['milestones.md']='# Reading-list milestones\n\n'+approval+'\n\n'+proposal.slice(milestoneStart,milestoneEnd).replaceAll('(spec.md','(spec.md');
files['README.md']='# Reading-list plan index\n\n'+approval+'\n\n[Spec](spec.md) · [Complete approved proposal](ticket-proposal.md) · [Milestones and QA](milestones.md) · [Preserved v1 draft](drafts/v1/spec.md)\n\nInitial version: no prior approved plan or completed-ticket evidence.\n\n| Ticket | Blocked by | Readiness | Milestone |\n| --- | --- | --- | --- |\n'+ids.map((id,i)=>`| [${id}: ${slugs[i].replaceAll('-',' ')}](issues/${id}-${slugs[i]}.md) | ${edges[id].join(', ')||'None'} | ready-for-agent | ${Object.keys(groups)[gid[id]]} |`).join('\n')+'\n\nPreferred execution order: 01, 02, 03, 04, 05. Initial eligible group: M1 (01,02), with only 01 technically unblocked. M2 waits for human M1 acceptance; M3 waits for human M2 acceptance. No run has started and no ticket is claimed Done.\n\nFinal M3 QA cumulatively covers all five tickets and overall acceptance. Every milestone is not yet requested/accepted. Ticket Done, milestone accepted and feature complete remain distinct; plan approval supplies none of these execution or QA outcomes.\n';
if(process.argv.includes('--publish')){
 fs.mkdirSync(path.join(base,'issues'));
 for(const [name,content] of Object.entries(files))fs.writeFileSync(path.join(base,name),content);
 console.log('Published '+Object.keys(files).length+' files after validation; preserved original draft.');
}else console.log('Prepublication validation passed: five complete bodies; unique IDs; acyclic edges; 2/2/1 membership; final coverage; roles/gate; no destination collisions.');
